```java
import java.util.*;
import java.util.concurrent.*;

public class Tasks {
    static int work(int n) {
        if (n == 2) throw new IllegalStateException("task 2 failed");
        return n * 10;
    }

    public static void main(String[] args) throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(3);
        try {
            List<Future<Integer>> futures = new ArrayList<>();
            for (int n = 1; n <= 3; n++) {
                int id = n;
                futures.add(pool.submit(() -> work(id)));      // Callable<Integer>.
            }
            for (Future<Integer> f : futures) {
                try {
                    System.out.println(f.get(2, TimeUnit.SECONDS));   // wait, bounded.
                } catch (ExecutionException e) {
                    System.out.println("failed: " + e.getCause().getMessage());
                } catch (TimeoutException e) {
                    f.cancel(true);
                    System.out.println("timed out");
                }
            }
        } finally {
            pool.shutdown();                                     // always release workers.
        }
    }
}
```

Output: 10, failed: task 2 failed, 30.

